SET NAMES utf8mb4;
USE manufacturing_risk;
SET FOREIGN_KEY_CHECKS = 0;
CREATE TABLE plant (plant_id VARCHAR(20) PRIMARY KEY, plant_name VARCHAR(100) NOT NULL, workshop_name VARCHAR(100) NOT NULL, line_name VARCHAR(100) NOT NULL, area_code VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL) ENGINE=InnoDB;
CREATE TABLE customer (customer_id VARCHAR(20) PRIMARY KEY, customer_name VARCHAR(100) NOT NULL, customer_level VARCHAR(20) NOT NULL, industry VARCHAR(50) NOT NULL, credit_limit DECIMAL(14,2) NOT NULL, approved_status VARCHAR(20) NOT NULL) ENGINE=InnoDB;
CREATE TABLE supplier (supplier_id VARCHAR(20) PRIMARY KEY, supplier_name VARCHAR(100) NOT NULL, supplier_level VARCHAR(20) NOT NULL, qualification_status VARCHAR(20) NOT NULL, qualification_expire_at DATE NOT NULL, risk_level VARCHAR(20) NOT NULL) ENGINE=InnoDB;
CREATE TABLE employee (employee_id VARCHAR(20) PRIMARY KEY, employee_name VARCHAR(60) NOT NULL, role_name VARCHAR(40) NOT NULL, team_name VARCHAR(60) NOT NULL, certification_type VARCHAR(60), certification_expire_at DATE, status VARCHAR(20) NOT NULL) ENGINE=InnoDB;
CREATE TABLE material (material_id VARCHAR(20) PRIMARY KEY, material_name VARCHAR(100) NOT NULL, material_type VARCHAR(20) NOT NULL, specification VARCHAR(100) NOT NULL, grade_name VARCHAR(60) NOT NULL, uom VARCHAR(10) NOT NULL, shelf_life_days INT, is_critical TINYINT(1) NOT NULL, revision VARCHAR(20) NOT NULL) ENGINE=InnoDB;
CREATE TABLE equipment (equipment_id VARCHAR(20) PRIMARY KEY, plant_id VARCHAR(20) NOT NULL, equipment_name VARCHAR(100) NOT NULL, equipment_type VARCHAR(40) NOT NULL, criticality VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, calibration_due_at DATE, maintenance_due_at DATE, FOREIGN KEY (plant_id) REFERENCES plant(plant_id)) ENGINE=InnoDB;
CREATE TABLE bom (bom_id VARCHAR(20) PRIMARY KEY, parent_material_id VARCHAR(20) NOT NULL, component_material_id VARCHAR(20) NOT NULL, qty_per DECIMAL(12,4) NOT NULL, scrap_rate DECIMAL(8,4) NOT NULL, revision VARCHAR(20) NOT NULL, FOREIGN KEY (parent_material_id) REFERENCES material(material_id), FOREIGN KEY (component_material_id) REFERENCES material(material_id)) ENGINE=InnoDB;
CREATE TABLE sales_order (sales_order_id VARCHAR(20) PRIMARY KEY, customer_id VARCHAR(20) NOT NULL, material_id VARCHAR(20) NOT NULL, order_qty INT NOT NULL, due_date DATE NOT NULL, priority VARCHAR(20) NOT NULL, unit_price DECIMAL(12,2) NOT NULL, revision VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY (customer_id) REFERENCES customer(customer_id), FOREIGN KEY (material_id) REFERENCES material(material_id)) ENGINE=InnoDB;
CREATE TABLE purchase_order (purchase_order_id VARCHAR(20) PRIMARY KEY, supplier_id VARCHAR(20) NOT NULL, material_id VARCHAR(20) NOT NULL, ordered_qty INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, promise_date DATE NOT NULL, approved_by VARCHAR(20), status VARCHAR(20) NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY (supplier_id) REFERENCES supplier(supplier_id), FOREIGN KEY (material_id) REFERENCES material(material_id), FOREIGN KEY (approved_by) REFERENCES employee(employee_id)) ENGINE=InnoDB;
CREATE TABLE receipt (receipt_id VARCHAR(20) PRIMARY KEY, purchase_order_id VARCHAR(20) NOT NULL, supplier_lot_no VARCHAR(40) NOT NULL, received_qty INT NOT NULL, warehouse_id VARCHAR(20) NOT NULL, received_at DATETIME NOT NULL, receiver_id VARCHAR(20) NOT NULL, FOREIGN KEY (purchase_order_id) REFERENCES purchase_order(purchase_order_id), FOREIGN KEY (receiver_id) REFERENCES employee(employee_id)) ENGINE=InnoDB;
CREATE TABLE iqc_inspection (iqc_id VARCHAR(20) PRIMARY KEY, receipt_id VARCHAR(20) NOT NULL, inspection_status VARCHAR(20) NOT NULL, sample_qty INT NOT NULL, defect_qty INT NOT NULL, inspector_id VARCHAR(20) NOT NULL, completed_at DATETIME, FOREIGN KEY (receipt_id) REFERENCES receipt(receipt_id), FOREIGN KEY (inspector_id) REFERENCES employee(employee_id)) ENGINE=InnoDB;
CREATE TABLE inventory (inventory_id VARCHAR(20) PRIMARY KEY, material_id VARCHAR(20) NOT NULL, lot_no VARCHAR(40) NOT NULL, warehouse_id VARCHAR(20) NOT NULL, quantity INT NOT NULL, quality_status VARCHAR(20) NOT NULL, received_at DATE NOT NULL, expiry_date DATE, FOREIGN KEY (material_id) REFERENCES material(material_id)) ENGINE=InnoDB;
CREATE TABLE work_order (work_order_id VARCHAR(20) PRIMARY KEY, sales_order_id VARCHAR(20), plant_id VARCHAR(20) NOT NULL, material_id VARCHAR(20) NOT NULL, planned_qty INT NOT NULL, completed_qty INT NOT NULL, bom_revision VARCHAR(20) NOT NULL, routing_revision VARCHAR(20) NOT NULL, planned_start_at DATETIME NOT NULL, planned_end_at DATETIME NOT NULL, status VARCHAR(20) NOT NULL, FOREIGN KEY (sales_order_id) REFERENCES sales_order(sales_order_id), FOREIGN KEY (plant_id) REFERENCES plant(plant_id), FOREIGN KEY (material_id) REFERENCES material(material_id)) ENGINE=InnoDB;
CREATE TABLE material_issue (issue_id VARCHAR(20) PRIMARY KEY, work_order_id VARCHAR(20) NOT NULL, material_id VARCHAR(20) NOT NULL, lot_no VARCHAR(40) NOT NULL, issue_qty INT NOT NULL, issued_by VARCHAR(20) NOT NULL, issued_at DATETIME NOT NULL, FOREIGN KEY (work_order_id) REFERENCES work_order(work_order_id), FOREIGN KEY (material_id) REFERENCES material(material_id), FOREIGN KEY (issued_by) REFERENCES employee(employee_id)) ENGINE=InnoDB;
CREATE TABLE operation_report (operation_report_id VARCHAR(20) PRIMARY KEY, work_order_id VARCHAR(20) NOT NULL, operation_seq INT NOT NULL, good_qty INT NOT NULL, scrap_qty INT NOT NULL, labor_hours DECIMAL(8,2) NOT NULL, operator_id VARCHAR(20) NOT NULL, reported_at DATETIME NOT NULL, FOREIGN KEY (work_order_id) REFERENCES work_order(work_order_id), FOREIGN KEY (operator_id) REFERENCES employee(employee_id)) ENGINE=InnoDB;
CREATE TABLE ipqc_inspection (ipqc_id VARCHAR(20) PRIMARY KEY, work_order_id VARCHAR(20) NOT NULL, operation_seq INT NOT NULL, measured_value DECIMAL(12,4) NOT NULL, lsl DECIMAL(12,4) NOT NULL, usl DECIMAL(12,4) NOT NULL, result VARCHAR(20) NOT NULL, inspector_id VARCHAR(20) NOT NULL, equipment_id VARCHAR(20) NOT NULL, inspected_at DATETIME NOT NULL, FOREIGN KEY (work_order_id) REFERENCES work_order(work_order_id), FOREIGN KEY (inspector_id) REFERENCES employee(employee_id), FOREIGN KEY (equipment_id) REFERENCES equipment(equipment_id)) ENGINE=InnoDB;
CREATE TABLE finished_goods (completion_id VARCHAR(20) PRIMARY KEY, work_order_id VARCHAR(20) NOT NULL, lot_no VARCHAR(40) NOT NULL, serial_range VARCHAR(100), good_qty INT NOT NULL, quality_status VARCHAR(20) NOT NULL, warehouse_id VARCHAR(20) NOT NULL, completed_at DATETIME NOT NULL, FOREIGN KEY (work_order_id) REFERENCES work_order(work_order_id)) ENGINE=InnoDB;
CREATE TABLE shipment (shipment_id VARCHAR(20) PRIMARY KEY, customer_id VARCHAR(20) NOT NULL, sales_order_id VARCHAR(20) NOT NULL, material_id VARCHAR(20) NOT NULL, lot_no VARCHAR(40) NOT NULL, ship_qty INT NOT NULL, quality_status VARCHAR(20) NOT NULL, released_by VARCHAR(20), ship_at DATETIME NOT NULL, FOREIGN KEY (customer_id) REFERENCES customer(customer_id), FOREIGN KEY (sales_order_id) REFERENCES sales_order(sales_order_id), FOREIGN KEY (material_id) REFERENCES material(material_id), FOREIGN KEY (released_by) REFERENCES employee(employee_id)) ENGINE=InnoDB;
CREATE TABLE customer_complaint (complaint_id VARCHAR(20) PRIMARY KEY, customer_id VARCHAR(20) NOT NULL, shipment_id VARCHAR(20), defect_code VARCHAR(40) NOT NULL, severity VARCHAR(20) NOT NULL, claim_amount DECIMAL(12,2) NOT NULL, returned_qty INT NOT NULL, status VARCHAR(20) NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY (customer_id) REFERENCES customer(customer_id), FOREIGN KEY (shipment_id) REFERENCES shipment(shipment_id)) ENGINE=InnoDB;
CREATE TABLE maintenance_order (maintenance_order_id VARCHAR(20) PRIMARY KEY, equipment_id VARCHAR(20) NOT NULL, failure_code VARCHAR(40) NOT NULL, downtime_minutes INT NOT NULL, technician_id VARCHAR(20) NOT NULL, loto_required TINYINT(1) NOT NULL, acceptance_status VARCHAR(20) NOT NULL, started_at DATETIME NOT NULL, completed_at DATETIME, FOREIGN KEY (equipment_id) REFERENCES equipment(equipment_id), FOREIGN KEY (technician_id) REFERENCES employee(employee_id)) ENGINE=InnoDB;
CREATE TABLE business_event (event_id VARCHAR(20) PRIMARY KEY, event_type VARCHAR(60) NOT NULL, entity_type VARCHAR(40) NOT NULL, entity_id VARCHAR(40) NOT NULL, source_system VARCHAR(20) NOT NULL, operator_id VARCHAR(20), business_at DATETIME NOT NULL, trace_id VARCHAR(40) NOT NULL, payload_json JSON) ENGINE=InnoDB;
SET FOREIGN_KEY_CHECKS = 1;
